select
  id, level, table_code, table_name, field, field_name, field_type, parent_table, state, order_num, create_time, is_field
from patient_enrollment_condition_tree


        and id = #{id}


        and level = #{level}


        and table_code = #{tableCode}


        and table_name = #{tableName}


        and field = #{field}


        and field_name = #{fieldName}


        and field_type = #{fieldType}


        and parent_table = #{parentTable}


        and state = #{state}


        and order_num = #{orderNum}


        and create_time = #{createTime}


        and is_field = #{isField}


order by level asc , order_num asc
limit #{pageable.pageSize} OFFSET #{pageable.offset}

